# Let me predict for test input
# 2s at: (8,3), (10,9), (11,5), (15,3), (17,8), (25,2), (25,4)

# For each 2, find offset positions where 5s should appear
# Pattern from Demo 2: 5 at 2 manhattan from 2

two_positions = [(8,3), (10,9), (11,5), (15,3), (17,8), (25,2), (25,4)]
background = 6

# Let me just try: 5s at all positions 2 manhattan from each 2 (not overlapping other non-6)
print("5 positions at 2 manhattan from 2s:")
five_candidates = []
non_6_pos = set(p[:2] for p in [(4,7,3), (6,2,0), (6,3,0), (7,2,0), (8,3,2), (10,9,2), (11,5,2), (13,11,3), (15,3,2), (17,8,2), (19,3,3), (21,11,5), (22,11,3), (25,2,3), (25,4,2)])

for r2, c2 in two_positions:
    for r in range(28):
        for c in range(12):
            dist = abs(r - r2) + abs(c - c2)
            if dist == 2:
                if (r, c) not in non_6_pos:
                    five_candidates.append((r, c))

print(sorted(five_candidates))

# That's still a lot. Let me be more selective - only 45 degrees diagonals
print("\nDiagonal offsets only (±1,±1) from 2s:")
diag_candidates = []
for r2, c2 in two_positions:
    # Diagonal: (r2±1, c2±1)
    for dr in [-1, 1]:
        for dc in [-1, 1]:
            r, c = r2 + dr, c2 + dc
            if 0 <= r < 28 and 0 <= c < 12:
                if (r, c) not in non_6_pos:
                    diag_candidates.append((r, c))

print(sorted(set(diag_candidates)))

